import hashlib
import logging
from typing import Any

import requests
from django.core.cache import cache

logger = logging.getLogger(__name__)


class GooglePlacesUpstreamError(Exception):
    """Raised when Google Places returns an unusable response."""


class GooglePlacesService:
    AUTOCOMPLETE_URL = "https://places.googleapis.com/v1/places:autocomplete"
    DETAILS_URL_TEMPLATE = "https://places.googleapis.com/v1/places/{place_id}"
    AUTOCOMPLETE_TIMEOUT_SECONDS = 5
    DETAILS_TIMEOUT_SECONDS = 5
    AUTOCOMPLETE_CACHE_SECONDS = 60
    DETAILS_CACHE_SECONDS = 24 * 60 * 60
    AUTOCOMPLETE_FIELD_MASK = ",".join(
        [
            "suggestions.placePrediction.placeId",
            "suggestions.placePrediction.text.text",
            "suggestions.placePrediction.structuredFormat.mainText.text",
            "suggestions.placePrediction.structuredFormat.secondaryText.text",
        ]
    )
    DETAILS_BASE_FIELDS = (
        "id",
        "formattedAddress",
        "location",
        "addressComponents.longText",
        "addressComponents.shortText",
        "addressComponents.types",
    )
    DETAILS_EXPAND_FIELDS = {
        "display": ("displayName", "shortFormattedAddress"),
        "maps": ("googleMapsUri",),
        "types": ("primaryType", "types"),
        "business": (
            "businessStatus",
            "websiteUri",
            "nationalPhoneNumber",
            "internationalPhoneNumber",
        ),
        "hours": ("regularOpeningHours", "currentOpeningHours"),
    }
    DETAILS_FIELD_MASK = ",".join(DETAILS_BASE_FIELDS)

    @classmethod
    def autocomplete(
        cls,
        *,
        api_key: str,
        query: str,
        session_token: str | None = None,
        requests_module: Any = requests,
    ) -> list[dict[str, str | None]]:
        normalized_query = " ".join(query.split()).strip()
        cache_key = cls._autocomplete_cache_key(normalized_query, session_token)
        cached: list[dict[str, str | None]] | None = cache.get(cache_key)
        if cached is not None:
            return cached

        payload: dict[str, Any] = {"input": normalized_query}
        if session_token:
            payload["sessionToken"] = session_token

        response = cls._post_json(
            requests_module=requests_module,
            url=cls.AUTOCOMPLETE_URL,
            api_key=api_key,
            payload=payload,
            field_mask=cls.AUTOCOMPLETE_FIELD_MASK,
            timeout=cls.AUTOCOMPLETE_TIMEOUT_SECONDS,
            operation="autocomplete",
        )

        suggestions = [
            suggestion
            for item in response.get("suggestions", [])
            if isinstance(item, dict)
            for suggestion in [cls._normalize_suggestion(item.get("placePrediction"))]
            if suggestion is not None
        ]
        cache.set(cache_key, suggestions, cls.AUTOCOMPLETE_CACHE_SECONDS)
        return suggestions

    @classmethod
    def get_place_details(
        cls,
        *,
        api_key: str,
        place_id: str,
        session_token: str | None = None,
        expand: object = None,
        requests_module: Any = requests,
    ) -> dict[str, Any]:
        normalized_place_id = place_id.strip()
        normalized_expand = cls.normalize_expand(expand)
        field_mask = cls._details_field_mask(normalized_expand)
        cache_key = cls._details_cache_key(normalized_place_id, normalized_expand)
        details: dict[str, Any] | None = cache.get(cache_key)
        if details is not None:
            return details

        headers = {
            "X-Goog-Api-Key": api_key,
            "X-Goog-FieldMask": field_mask,
        }
        params = {"sessionToken": session_token} if session_token else None
        url = cls.DETAILS_URL_TEMPLATE.format(place_id=normalized_place_id)

        try:
            response = requests_module.get(
                url,
                headers=headers,
                params=params,
                timeout=cls.DETAILS_TIMEOUT_SECONDS,
            )
        except requests.RequestException as exc:
            logger.warning(
                "Google Places details request failed: %s", exc.__class__.__name__
            )
            raise GooglePlacesUpstreamError("details_request_failed") from exc

        payload = cls._parse_response_json(response, operation="details")
        place = cls._normalize_place(payload, normalized_place_id, normalized_expand)
        cache.set(cache_key, place, cls.DETAILS_CACHE_SECONDS)
        return place

    @classmethod
    def normalize_expand(cls, expand: object) -> tuple[str, ...]:
        if expand in (None, "", []):
            return ()

        raw_values: list[object]
        if isinstance(expand, str):
            raw_values = [part.strip() for part in expand.split(",") if part.strip()]
        elif isinstance(expand, (list, tuple)):
            raw_values = expand
        else:
            raise ValueError(
                "Expand must be a list of strings or a comma-separated string."
            )

        requested: set[str] = set()
        for value in raw_values:
            if not isinstance(value, str):
                raise ValueError("Expand values must be strings.")
            normalized = value.strip()
            if normalized:
                requested.add(normalized)

        for value in sorted(requested):
            if value not in cls.DETAILS_EXPAND_FIELDS:
                raise ValueError(f"Unsupported expand value: {value}.")

        return tuple(
            value for value in cls.DETAILS_EXPAND_FIELDS.keys() if value in requested
        )

    @classmethod
    def _post_json(
        cls,
        *,
        requests_module: Any,
        url: str,
        api_key: str,
        payload: dict[str, Any],
        field_mask: str,
        timeout: int,
        operation: str,
    ) -> dict[str, Any]:
        try:
            response = requests_module.post(
                url,
                headers={
                    "Content-Type": "application/json",
                    "X-Goog-Api-Key": api_key,
                    "X-Goog-FieldMask": field_mask,
                },
                json=payload,
                timeout=timeout,
            )
        except requests.RequestException as exc:
            logger.warning(
                "Google Places %s request failed: %s", operation, exc.__class__.__name__
            )
            raise GooglePlacesUpstreamError(f"{operation}_request_failed") from exc

        return cls._parse_response_json(response, operation=operation)

    @classmethod
    def _parse_response_json(cls, response: Any, *, operation: str) -> dict[str, Any]:
        if response.status_code != 200:
            logger.warning(
                "Google Places %s returned non-200 status=%s",
                operation,
                response.status_code,
            )
            raise GooglePlacesUpstreamError(f"{operation}_http_{response.status_code}")

        try:
            payload = response.json()
        except ValueError as exc:
            logger.warning("Google Places %s returned invalid JSON", operation)
            raise GooglePlacesUpstreamError(f"{operation}_invalid_json") from exc

        if not isinstance(payload, dict):
            logger.warning(
                "Google Places %s returned unexpected payload type", operation
            )
            raise GooglePlacesUpstreamError(f"{operation}_invalid_payload")

        return payload

    @classmethod
    def _normalize_suggestion(
        cls, place_prediction: Any
    ) -> dict[str, str | None] | None:
        if not isinstance(place_prediction, dict):
            return None

        description = cls._safe_nested_text(place_prediction, "text")
        place_id = place_prediction.get("placeId")
        if not isinstance(description, str) or not description.strip():
            return None
        if not isinstance(place_id, str) or not place_id.strip():
            return None

        structured = place_prediction.get("structuredFormat") or {}
        return {
            "place_id": place_id,
            "description": description,
            "primary_text": cls._safe_nested_text(structured, "mainText")
            or description,
            "secondary_text": cls._safe_nested_text(structured, "secondaryText"),
        }

    @classmethod
    def _normalize_place(
        cls,
        payload: dict[str, Any],
        fallback_place_id: str,
        expand: tuple[str, ...] = (),
    ) -> dict[str, Any]:
        formatted_address = payload.get("formattedAddress")
        location = payload.get("location") or {}
        address_components = payload.get("addressComponents") or []
        raw_place_id = payload.get("id") or fallback_place_id
        normalized_place_id = (
            raw_place_id.removeprefix("places/")
            if isinstance(raw_place_id, str)
            else fallback_place_id
        )

        place: dict[str, Any] = {
            "place_id": normalized_place_id,
            "description": formatted_address or fallback_place_id,
            "formatted_address": formatted_address or fallback_place_id,
            "latitude": location.get("latitude"),
            "longitude": location.get("longitude"),
            "address_components": [
                {
                    "long_text": component.get("longText"),
                    "short_text": component.get("shortText"),
                    "types": component.get("types") or [],
                }
                for component in address_components
                if isinstance(component, dict)
            ],
        }

        if "display" in expand:
            display_name = cls._safe_nested_text(payload, "displayName")
            short_formatted_address = payload.get("shortFormattedAddress")
            place["display_name"] = display_name
            place["short_formatted_address"] = (
                short_formatted_address
                if isinstance(short_formatted_address, str)
                else None
            )
            if display_name:
                place["description"] = display_name

        if "maps" in expand:
            google_maps_uri = payload.get("googleMapsUri")
            place["google_maps_uri"] = (
                google_maps_uri if isinstance(google_maps_uri, str) else None
            )

        if "types" in expand:
            primary_type = payload.get("primaryType")
            raw_types = payload.get("types")
            place["primary_type"] = (
                primary_type if isinstance(primary_type, str) else None
            )
            place["types"] = (
                [value for value in raw_types if isinstance(value, str)]
                if isinstance(raw_types, list)
                else []
            )

        if "business" in expand:
            for source_key, target_key in (
                ("businessStatus", "business_status"),
                ("websiteUri", "website_uri"),
                ("nationalPhoneNumber", "national_phone_number"),
                ("internationalPhoneNumber", "international_phone_number"),
            ):
                value = payload.get(source_key)
                place[target_key] = value if isinstance(value, str) else None

        if "hours" in expand:
            place["regular_opening_hours"] = payload.get("regularOpeningHours")
            place["current_opening_hours"] = payload.get("currentOpeningHours")

        return place

    @staticmethod
    def _safe_nested_text(data: dict[str, Any], key: str) -> str | None:
        value = data.get(key)
        if isinstance(value, dict):
            text = value.get("text")
            if isinstance(text, str):
                return text
        return None

    @classmethod
    def _autocomplete_cache_key(cls, query: str, session_token: str | None) -> str:
        digest = hashlib.sha256(
            f"{query.lower()}::{session_token or ''}".encode()
        ).hexdigest()
        return f"google-places:autocomplete:{digest}"

    @classmethod
    def _details_field_mask(cls, expand: tuple[str, ...]) -> str:
        fields = list(cls.DETAILS_BASE_FIELDS)
        for expand_value in expand:
            fields.extend(cls.DETAILS_EXPAND_FIELDS[expand_value])
        return ",".join(fields)

    @classmethod
    def _details_cache_key(cls, place_id: str, expand: tuple[str, ...]) -> str:
        digest = hashlib.sha256(f"{place_id}::{','.join(expand)}".encode()).hexdigest()
        return f"google-places:details:{digest}"
